WITH scored AS (SELECT id, location, RANK() OVER (PARTITION BY location ORDER BY budget NULLS LAST) AS budget_rank, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) AS budget_share FROM departments WHERE budget >= 3199000) SELECT id, location, budget_rank, cumulative_budget, CASE WHEN location RLIKE '^(Chiang Mai|London)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS location_zone FROM scored ORDER BY location_zone;
